const HOME='C:/Users/eric_rash';
const cutoff=Date.now()-30*864e5;
const root=HOME+'/.claude/projects';
let files=[];
for(const s of fs.readdirSync(root)){ const d=path.join(root,s); let st; try{st=fs.statSync(d)}catch{continue} if(!st.isDirectory())continue; for(const f of fs.readdirSync(d)){ if(!f.endsWith('.jsonl'))continue; const p=path.join(d,f); const fs2=fs.statSync(p); if(fs2.mtimeMs>=cutoff) files.push({p,size:fs2.size,slug:s}); } }
console.log('sessions (jsonl modified <30d):',files.length,'total MB',(files.reduce((a,b)=>a+b.size,0)/1048576).toFixed(0));
const c={memsearchSearchCalls:0, msSearchCalls:0, memsearchAnyBash:0, memsearchExpandTranscript:0, sessionsWithMemsearchSearch:new Set(), sessionsWithMsSearch:new Set(), rgOrGrepOnMemoryDirs:0, ctxSearchCalls:0, readOfMemoryFiles:0, sessionStartInjections:0, injectionCharsSum:0, injectionSamples:0, memsearchPointerInjections:0, userPromptsWithRecallPhrasing:0, skillMemoryWrite:0, hookErrorsMentioned:0, sessionsWithGrepMemory:new Set()};
const injSizes=[];
(async()=>{
for(const f of files){
  const rl=readline.createInterface({input:fs.createReadStream(f.p,{encoding:'utf8'}),crlfDelay:Infinity});
  for await(const line of rl){
    if(line.length<20)continue;
    if(line.includes('memsearch search')||line.includes('ms-search')){
      let j; try{j=JSON.parse(line)}catch{continue}
      const content=j.message&&j.message.content; if(!Array.isArray(content))continue;
      for(const b of content){ if(b.type==='tool_use'&&(b.name==='Bash'||b.name==='PowerShell')){ const cmd=(b.input&&b.input.command)||''; if(/memsearch\s+search/.test(cmd)){c.memsearchSearchCalls++; c.sessionsWithMemsearchSearch.add(f.p);} if(/\bms-search\b/.test(cmd)){c.msSearchCalls++; c.sessionsWithMsSearch.add(f.p);} if(/memsearch\s+(expand|transcript)/.test(cmd))c.memsearchExpandTranscript++; if(/\bmemsearch\b/.test(cmd))c.memsearchAnyBash++; } }
    }
    if(line.includes('"tool_use"')&&(line.includes('/memory/')||line.includes('global-memory')||line.includes('claude-memory-compiler')||line.includes('SecondBrain'))){
      let j; try{j=JSON.parse(line)}catch{continue}
      const content=j.message&&j.message.content; if(!Array.isArray(content))continue;
      for(const b of content){ if(b.type!=='tool_use')continue; const s=JSON.stringify(b.input||{}); if(b.name==='Grep'&&/memory|global-memory|claude-memory-compiler|SecondBrain/.test(s)){c.rgOrGrepOnMemoryDirs++; c.sessionsWithGrepMemory.add(f.p);} if((b.name==='Bash'||b.name==='PowerShell')&&/\b(rg|grep)\b/.test(s)&&/memory|SecondBrain|claude-memory-compiler/.test(s)){c.rgOrGrepOnMemoryDirs++; c.sessionsWithGrepMemory.add(f.p);} if(b.name==='Read'&&/\/memory\/|global-memory|claude-memory-compiler\/(daily|knowledge)/.test(s))c.readOfMemoryFiles++; }
    }
    if(line.includes('ctx_search'))c.ctxSearchCalls+= (line.match(/"name":"mcp__plugin_context-mode_context-mode__ctx_search"/g)||[]).length;
    if(line.includes('"type":"system"')&&line.includes('hook')&&/error|failed|timed out/i.test(line))c.hookErrorsMentioned++;
    if(line.includes('SessionStart')&&line.includes('additionalContext')){ let j; try{j=JSON.parse(line)}catch{continue} const s=JSON.stringify(j); c.sessionStartInjections++; injSizes.push(s.length); if(s.includes('memsearch search'))c.memsearchPointerInjections++; }
  }
}
c.sessionsWithMemsearchSearch=c.sessionsWithMemsearchSearch.size; c.sessionsWithMsSearch=c.sessionsWithMsSearch.size; c.sessionsWithGrepMemory=c.sessionsWithGrepMemory.size;
console.log(JSON.stringify(c,null,1));
if(injSizes.length){injSizes.sort((a,b)=>a-b); console.log('SessionStart injection record sizes (chars): n',injSizes.length,'median',injSizes[Math.floor(injSizes.length/2)],'max',injSizes[injSizes.length-1]);}
})();

