const fs=require('fs'),path=require('path'),readline=require('readline');
const HOME='C:/Users/eric_rash'; const cutoff=Date.now()-30*864e5; const root=HOME+'/.claude/projects';
let files=[]; for(const s of fs.readdirSync(root)){const d=path.join(root,s); let st; try{st=fs.statSync(d)}catch{continue} if(!st.isDirectory())continue; for(const f of fs.readdirSync(d)){ if(!f.endsWith('.jsonl'))continue; const p=path.join(d,f); if(fs.statSync(p).mtimeMs>=cutoff) files.push(p);} }
const byHook={}; const big=[]; const hookErr={}; let entrypoints={}; let sessionsSdk=0;
(async()=>{
for(const f of files){
  let firstLine=true;
  const rl=readline.createInterface({input:fs.createReadStream(f,{encoding:'utf8'}),crlfDelay:Infinity});
  for await(const line of rl){
    if(firstLine){ firstLine=false; const m=line.match(/"entrypoint":"([^"]+)"/); const e=m?m[1]:'?'; entrypoints[e]=(entrypoints[e]||0)+1; }
    if(line.includes('SessionStart')&&line.includes('additionalContext')){
      let j; try{j=JSON.parse(line)}catch{continue}
      const s=JSON.stringify(j);
      // classify by content marker
      let k='other';
      if(s.includes('User profile')||s.includes('KeystoneOS snapshot')||s.includes('unified-snapshot'))k='keystone-unified-snapshot';
      else if(s.includes('knowledge/index.md')||s.includes('Recent Daily Log')||s.includes('compiled'))k='compiler-session-start';
      else if(s.includes('superpowers'))k='superpowers-quiet';
      else if(s.includes('context-mode')||s.includes('ctx_'))k='context-mode';
      else if(s.includes('herdr'))k='herdr';
      byHook[k]=byHook[k]||{n:0,sum:0,max:0}; byHook[k].n++; byHook[k].sum+=s.length; if(s.length>byHook[k].max)byHook[k].max=s.length;
      if(s.length>50000) big.push({f:path.basename(f),len:s.length,head:s.slice(0,160).replace(/\s+/g,' ')});
    }
    if(line.includes('hook')&&(line.includes('timed out')||line.includes('exit code')||line.includes('failed'))&&line.includes('"type":"system"')){
      const m=line.match(/(memsearch-sync|session-end\.py|session-start\.py|keystone-unified-snapshot|transcript-capture|router\.py|shadow_hook|herdr|superpowers-quiet|context-mode-cache-heal|pre-compact|dcg)/); const k=m?m[1]:'unknown';
      const t=/timed out/.test(line)?'timeout':'fail'; hookErr[k+':'+t]=(hookErr[k+':'+t]||0)+1;
    }
  }
}
console.log('entrypoints:',JSON.stringify(entrypoints));
for(const [k,v] of Object.entries(byHook)) console.log(`${k}: n=${v.n} avg=${Math.round(v.sum/v.n)} max=${v.max}`);
big.sort((a,b)=>b.len-a.len); console.log('injections >50k chars:',big.length); big.slice(0,5).forEach(b=>console.log(' ',b.len,b.f,'::',b.head));
console.log('hook errors in system lines (30d):',JSON.stringify(hookErr));
})();

