      if(len>200000&&bigSamples.length<2){ const c=j.message&&j.message.content; const txt=typeof c==='string'?c:JSON.stringify(c); const i=txt.indexOf('additionalContext'); bigSamples.push({len, keys:Object.keys(j).join(','), around: txt.slice(Math.max(0,i-100), i+500).replace(/\s+/g,' '), markers: ['index.md','Recent Daily Log','KeystoneOS','superpowers','context-mode','User profile','knowledge/','# ','## '].map(m=>m+'='+(txt.split(m).length-1)).join(' ')}); }
    }
  }
  if(userText>=2)human++; else headless++;
  bySlug[slug]=(bySlug[slug]||0)+1;
}
console.log('sessions 30d:',files.length,'with>=2 human text prompts:',human,'else(headless/one-shot):',headless);
console.log('top slugs:',JSON.stringify(Object.entries(bySlug).sort((a,b)=>b[1]-a[1]).slice(0,8)));
for(const [k,v] of Object.entries(injBySource))console.log(`inject source=${k}: n=${v.n} avg=${Math.round(v.sum/v.n)} max=${v.max}`);
bigSamples.forEach(b=>console.log('\nBIG',b.len,'keys:',b.keys,'\n markers:',b.markers,'\n around:',b.around));
})();

